<?php require_once __DIR__.'/../../includes/tecnico.php'; exigir_tecnico();$codigo=trim((string)($_GET['codigo']??''));$db=obtener_conexion();$instrumento=null;$reparaciones=[];$error='';if($codigo!==''){$s=$db->prepare('SELECT i.*,c.nombre AS cliente_nombre FROM instrumento i INNER JOIN cliente c ON c.id_cliente=i.id_cliente WHERE i.codigo_qr=?');$s->execute([$codigo]);$instrumento=$s->fetch();if($instrumento){$s=$db->prepare('SELECT r.*,u.nombre AS tecnico FROM reparacion r INNER JOIN usuario u ON u.id_usuario=r.id_usuario WHERE r.id_instrumento=? ORDER BY r.fecha_ingreso DESC');$s->execute([$instrumento['id_instrumento']]);$reparaciones=$s->fetchAll();foreach($reparaciones as &$r){$x=$db->prepare('SELECT ru.cantidad,m.nombre FROM repuesto_utilizado ru INNER JOIN material m ON m.id_material=ru.id_material WHERE ru.id_reparacion=?');$x->execute([$r['id_reparacion']]);$r['repuestos']=$x->fetchAll();}unset($r);}else{$error='No existe un instrumento con ese código.';}}$titulo='Historial QR';require __DIR__.'/../../includes/header.php';?>
